def avatar(number, alt, initials):
    image = root / f'outputs/promotion-preview/reference-assets/avatar-{number}.jpg'
    if image.exists():
        src = 'data:image/jpeg;base64,' + base64.b64encode(image.read_bytes()).decode()
        return f'<img class="person-avatar" src="{src}" width="48" height="48" alt="{alt}" loading="lazy" decoding="async">'
    return f'<span class="person-avatar initials-avatar" aria-label="{alt}">{initials}</span>'

